static void text(struct cursor *c,char *p,size_t cap){uint32_t n=0;if(!c->in){if(bounded(p,cap)){c->bad=1;return;}n=(uint32_t)strlen(p);}u32(c,&n);if(!n||n>=cap){c->bad=1;return;}raw(c,p,n);if(c->in&&!c->bad){if(memchr(p,0,n)){c->bad=1;return;}p[n]=0;}}
